From af6514f2f3828dc39c96cd4686ef5c9d8368626f Mon Sep 17 00:00:00 2001
From: Kai Vehmanen <kai.vehmanen@linux.intel.com>
Date: Tue, 18 Oct 2022 15:13:32 +0300
Subject: [PATCH] ASoC: SOF: ipc4-mtrace: protect per-core nodes against
 multiple open
MIME-Version: 1.0
Content-Type: text/plain; charset=UTF-8
Content-Transfer-Encoding: 8bit

Add protection against multiple open of the mtrace/coreN debugfs
nodes. This is not supported in the implementation, and this will
show up as unexpected behaviour of the interface, and potential
use of already freed memory.

Fixes: f4ea22f7aa75 ("ASoC: SOF: ipc4: Add support for mtrace log extraction")
Signed-off-by: Kai Vehmanen <kai.vehmanen@linux.intel.com>
Reviewed-by: Péter Ujfalusi <peter.ujfalusi@linux.intel.com>
Reviewed-by: Pierre-Louis Bossart <pierre-louis.bossart@linux.intel.com>
Reviewed-by: Ranjani Sridharan <ranjani.sridharan@linux.intel.com>
Link: https://lore.kernel.org/r/20221018121332.20802-1-peter.ujfalusi@linux.intel.com
Signed-off-by: Mark Brown <broonie@kernel.org>

diff --git a/sound/soc/sof/ipc4-mtrace.c b/sound/soc/sof/ipc4-mtrace.c
index 9c7080041d08..70dea8ae706e 100644
--- a/sound/soc/sof/ipc4-mtrace.c
+++ b/sound/soc/sof/ipc4-mtrace.c
@@ -108,6 +108,7 @@ struct sof_mtrace_core_data {
 	int id;
 	u32 slot_offset;
 	void *log_buffer;
+	struct mutex buffer_lock; /* for log_buffer alloc/free */
 	u32 host_read_ptr;
 	u32 dsp_write_ptr;
 	/* pos update IPC arrived before the slot offset is known, queried */
@@ -128,14 +129,22 @@ static int sof_ipc4_mtrace_dfs_open(struct inode *inode, struct file *file)
 	struct sof_mtrace_core_data *core_data = inode->i_private;
 	int ret;

+	mutex_lock(&core_data->buffer_lock);
+
+	if (core_data->log_buffer) {
+		ret = -EBUSY;
+		goto out;
+	}
+
 	ret = debugfs_file_get(file->f_path.dentry);
 	if (unlikely(ret))
-		return ret;
+		goto out;

 	core_data->log_buffer = kmalloc(SOF_MTRACE_SLOT_SIZE, GFP_KERNEL);
 	if (!core_data->log_buffer) {
 		debugfs_file_put(file->f_path.dentry);
-		return -ENOMEM;
+		ret = -ENOMEM;
+		goto out;
 	}

 	ret = simple_open(inode, file);
@@ -144,6 +153,9 @@ static int sof_ipc4_mtrace_dfs_open(struct inode *inode, struct file *file)
 		debugfs_file_put(file->f_path.dentry);
 	}

+out:
+	mutex_unlock(&core_data->buffer_lock);
+
 	return ret;
 }

@@ -280,7 +292,10 @@ static int sof_ipc4_mtrace_dfs_release(struct inode *inode, struct file *file)

 	debugfs_file_put(file->f_path.dentry);

+	mutex_lock(&core_data->buffer_lock);
 	kfree(core_data->log_buffer);
+	core_data->log_buffer = NULL;
+	mutex_unlock(&core_data->buffer_lock);

 	return 0;
 }
@@ -563,6 +578,7 @@ static int ipc4_mtrace_init(struct snd_sof_dev *sdev)
 		struct sof_mtrace_core_data *core_data = &priv->cores[i];

 		init_waitqueue_head(&core_data->trace_sleep);
+		mutex_init(&core_data->buffer_lock);
 		core_data->sdev = sdev;
 		core_data->id = i;
 	}
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug arises from the lack of protection against multiple concurrent accesses to the `log_buffer` in the `sof_mtrace_core_data` structure. When multiple threads attempt to open the mtrace debugfs nodes simultaneously, it can lead to unexpected behavior, including the potential use of already freed memory, as the `log_buffer` may be allocated or freed by different threads without proper synchronization.

        Commit message:
        ASoC: SOF: ipc4-mtrace: protect per-core nodes against
 multiple open
MIME-Version: 1.0
Content-Type: text/plain; charset=UTF-8
Content-Transfer-Encoding: 8bit

Add protection against multiple open of the mtrace/coreN debugfs
nodes. This is not supported in the implementation, and this will
show up as unexpected behaviour of the interface, and potential
use of already freed memory.

Fixes: f4ea22f7aa75 ("ASoC: SOF: ipc4: Add support for mtrace log extraction")
Signed-off-by: Kai Vehmanen <kai.vehmanen@linux.intel.com>
Reviewed-by: Péter Ujfalusi <peter.ujfalusi@linux.intel.com>
Reviewed-by: Pierre-Louis Bossart <pierre-louis.bossart@linux.intel.com>
Reviewed-by: Ranjani Sridharan <ranjani.sridharan@linux.intel.com>
Link: https://lore.kernel.org/r/20221018121332.20802-1-peter.ujfalusi@linux.intel.com
Signed-off-by: Mark Brown <broonie@kernel.org>  

        Patch:
         	u32 slot_offset;
 	void *log_buffer;
+	struct mutex buffer_lock; /* for log_buffer alloc/free */
 	u32 host_read_ptr;
 	u32 dsp_write_ptr;

 static int sof_ipc4_mtrace_dfs_open(struct inode *inode, struct file *file)
 {
 	struct sof_mtrace_core_data *core_data = inode->i_private;
 	int ret;

+	mutex_lock(&core_data->buffer_lock);
+
+	if (core_data->log_buffer) {
+		ret = -EBUSY;
+		goto out;
+	}
+
 	ret = debugfs_file_get(file->f_path.dentry);
 	if (unlikely(ret))
-		return ret;
+		goto out;

 	core_data->log_buffer = kmalloc(SOF_MTRACE_SLOT_SIZE, GFP_KERNEL);
 	if (!core_data->log_buffer) {
 		debugfs_file_put(file->f_path.dentry);
-		return -ENOMEM;
+		ret = -ENOMEM;
+		goto out;
 	}

 	ret = simple_open(inode, file);
 	if (ret) {
 		kfree(core_data->log_buffer);
 		debugfs_file_put(file->f_path.dentry);
 	}

+out:
+	mutex_unlock(&core_data->buffer_lock);
+
 	return ret;
 }


 static int sof_ipc4_mtrace_dfs_release(struct inode *inode, struct file *file)
 {
 	struct sof_mtrace_core_data *core_data = inode->i_private;

 	debugfs_file_put(file->f_path.dentry);

+	mutex_lock(&core_data->buffer_lock);
 	kfree(core_data->log_buffer);
+	core_data->log_buffer = NULL;
+	mutex_unlock(&core_data->buffer_lock);

 	return 0;
 }


 static int ipc4_mtrace_init(struct snd_sof_dev *sdev)
 {
 	struct sof_ipc4_fw_data *ipc4_data = sdev->private;
 	struct sof_mtrace_priv *priv;
 	int i, ret;

 	if (sdev->fw_trace_data) {
 		dev_err(sdev->dev, "fw_trace_data has been already allocated\n");
 		return -EBUSY;
 	}

 	if (!ipc4_data->mtrace_log_bytes ||
 	    ipc4_data->mtrace_type != SOF_IPC4_MTRACE_INTEL_CAVS_2) {
 		sdev->fw_trace_is_supported = false;
 		return 0;
 	}

 	priv = devm_kzalloc(sdev->dev, struct_size(priv, cores, sdev->num_cores),
 			    GFP_KERNEL);
 	if (!priv)
 		return -ENOMEM;

 	sdev->fw_trace_data = priv;

 	/* Set initial values for mtrace parameters */
 	priv->state_info.aging_timer_period = DEFAULT_AGING_TIMER_PERIOD_MS;
 	priv->state_info.fifo_full_timer_period = DEFAULT_FIFO_FULL_TIMER_PERIOD_MS;
 	/* Only enable basefw logs initially (index 0 is always basefw) */
 	priv->state_info.logs_priorities_mask[0] = DEFAULT_LOGS_PRIORITIES_MASK;

 	for (i = 0; i < sdev->num_cores; i++) {
 		struct sof_mtrace_core_data *core_data = &priv->cores[i];

 		init_waitqueue_head(&core_data->trace_sleep);
+		mutex_init(&core_data->buffer_lock);
 		core_data->sdev = sdev;
 		core_data->id = i;
 	}

 	ret = ipc4_mtrace_enable(sdev);
 	if (ret) {
 		/*
 		 * Mark firmware tracing as not supported and return 0 to not
 		 * block the whole audio stack
 		 */
 		sdev->fw_trace_is_supported = false;
 		dev_dbg(sdev->dev, "initialization failed, fw tracing is disabled\n");
 		return 0;
 	}

 	sof_mtrace_find_core_slots(sdev);

 	ret = mtrace_debugfs_create(sdev);
 	if (ret)
 		ipc4_mtrace_disable(sdev);

 	return ret;
 }



